    audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + by + " user=" + user + " from=" + start
            + " to=" + end);
    return saved;
}

/** Whether the user is a viewer on the sheet: one who can change nothing. */
public boolean isViewer(String sheetId, String user) {
